import json


def render_dashboard(token, url):
    template = r'''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width">
<title>JarVis Maps Studio</title><style>
:root{font:16px system-ui;color:#102442;background:#edf3fb}*{box-sizing:border-box}body{max-width:1120px;margin:0 auto;padding:32px}
h1{font-size:32px;letter-spacing:-1px;margin:0}h2{font-size:20px}p{line-height:1.55}small{color:#53657d}header{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:28px}
section{background:white;padding:24px;border-radius:18px;margin-bottom:20px;border:1px solid #dbe5f1}.columns{display:grid;grid-template-columns:300px 1fr;gap:20px}
button{font:inherit;border:0;border-radius:10px;background:#1250ed;color:white;min-height:44px;padding:10px 16px;cursor:pointer}button:disabled{opacity:.5;cursor:wait}.item{display:block;width:100%;text-align:left;background:#edf3ff;color:#153b83;margin:10px 0;overflow-wrap:anywhere}
input{font:inherit;max-width:100%;padding:10px}#setup{width:190px;max-width:100%}#maps{max-height:560px;overflow:auto}canvas{width:100%;max-height:550px;object-fit:contain;image-rendering:pixelated;background:#2f3944;border-radius:12px}#detail{white-space:pre-wrap}#status{min-height:48px}a{color:#1250ed}:focus-visible{outline:3px solid #ff8a00;outline-offset:3px}@media(max-width:760px){body{padding:16px}.columns{grid-template-columns:1fr}header{align-items:flex-start}#setup{width:120px}}
</style><header><div><h1>JarVis Maps Studio</h1><p>Thu dữ liệu trên điện thoại. Phân tích và quản lý từng phòng trên PC.</p><small id="address"></small></div><img id="setup" src="/setup.png" alt="QR kết nối riêng; không chia sẻ"></header>
<section><h2>Nhập lượt chụp từ điện thoại</h2><p>Chép ZIP trong Download/JarVisMaps sang PC rồi chọn tại đây. Không cần điện thoại cùng Wi-Fi để nhập file.</p><input id="file" type="file" accept=".zip"><button id="upload">Nhập và phân tích</button><p id="status" role="status" aria-live="polite">Đang đọc trạng thái PC…</p><small>Ảnh xử lý cục bộ. Giữ ảnh gốc; map định vị không đồng nghĩa đường đi đã được kiểm tra.</small></section>
<div class="columns"><section><h2>Thư viện nhiều map</h2><button id="reload">Làm mới</button><div id="maps"></div></section><section><h2 id="name">Chọn một map</h2><button id="rename" hidden>Đổi tên</button><p id="detail">Map được giữ riêng theo ID và revision; dựng phòng mới không xóa phòng trước.</p><canvas id="floor" hidden></canvas><p id="legend" hidden>Đỏ: bề mặt cản · sáng: bằng chứng sàn · tối: chưa xác định · xanh: tuyến ứng viên. Đây là bản nháp bề mặt, chưa chứng minh khoảng trống toàn thân.</p><h2>Gợi ý đồ vật trên ảnh</h2><p id="objects">Chọn map để đọc báo cáo. Không tự đếm vật duy nhất từ các ảnh chồng lấn.</p></section></div>
<script>
const config=__CONFIG__;let selected=null,lastState='',selectionVersion=0;const element=id=>document.getElementById(id);element('address').textContent=config.url+' · chỉ dùng trong mạng riêng';
async function api(path,options={}){options.headers={...(options.headers||{}),Authorization:'Bearer '+config.token};const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw Error(data.error||'PC chưa xử lý được');return data}
async function refresh(){const data=await api('/maps');const target=element('maps');target.replaceChildren();for(const map of data.maps){const row=document.createElement('button');row.className='item';row.textContent=map.name+' · r'+map.revision+'\n'+map.registered+'/'+map.total+' ảnh · '+(map.navigationAllowed?'tuyến đã duyệt':'chưa duyệt đường đi');row.onclick=()=>show(map.id).catch(fail);target.append(row)}if(!data.maps.length)target.textContent='Chưa có map dựng thành công. Nhập ZIP để bắt đầu.'}
function fail(error){element('status').textContent=error.message}
async function show(identifier){const version=++selectionVersion,map=await api('/maps/'+encodeURIComponent(identifier));if(version!==selectionVersion)return;selected=map.id;element('name').textContent=map.name;element('rename').hidden=false;element('detail').textContent='ID: '+map.id+' · revision '+map.revision+'\nGhép '+map.registered+'/'+map.total+' ảnh. Hình học: '+map.geometryState+'\n'+(map.navigationAllowed?'Có tuyến được duyệt.':'Chưa đủ điều kiện bật chỉ đường.');element('floor').hidden=true;element('legend').hidden=true;
try{const geometry=await api('/maps/'+encodeURIComponent(identifier)+'/geometry');if(version!==selectionVersion)return;if(geometry.cells){const canvas=element('floor');canvas.width=geometry.width;canvas.height=geometry.height;const context=canvas.getContext('2d'),image=context.createImageData(canvas.width,canvas.height);const colors=[[47,57,68],[213,234,244],[230,80,70]];geometry.cells.forEach((value,index)=>{const row=Math.floor(index/canvas.width),column=index%canvas.width,offset=((canvas.height-row-1)*canvas.width+column)*4;image.data.set([...colors[value],255],offset)});context.putImageData(image,0,0);if(map.points.length){context.strokeStyle='#109aff';context.lineWidth=1.5;context.beginPath();map.points.forEach((point,index)=>{const column=(point.x-geometry.origin[0])/geometry.resolution,row=canvas.height-(point.z-geometry.origin[1])/geometry.resolution;index?context.lineTo(column,row):context.moveTo(column,row)});context.stroke();const marker=(point,label,color)=>{const x=(point.x-geometry.origin[0])/geometry.resolution,y=canvas.height-(point.z-geometry.origin[1])/geometry.resolution;context.beginPath();context.fillStyle=color;context.strokeStyle='#fff';context.lineWidth=1.5;context.arc(x,y,Math.max(2,Math.min(canvas.width,canvas.height)*.025),0,Math.PI*2);context.fill();context.stroke();context.fillStyle='#fff';context.font='bold 10px system-ui';context.textAlign='center';context.fillText(label,x,y-5)};marker(map.points[0],'A','#1454f5');marker(map.points[map.points.length-1],'B','#10a66a')}canvas.hidden=false;element('legend').hidden=false;element('detail').textContent+='\n'+geometry.depthFrames+' ảnh Depth dùng được. '+geometry.reason;if(geometry.route){element('detail').textContent+='\nTuyến A → B: '+Number(geometry.route.distanceMetres||0).toFixed(1)+' m · hành lang có bằng chứng '+Math.round((geometry.route.coverage||0)*100)+'%.'+'\n'+(geometry.route.reasonText||geometry.route.reason)+'\n'+geometry.route.note}}}catch(error){if(version!==selectionVersion)return;element('detail').textContent+='\nChưa có báo cáo hình học.'}
try{const report=await api('/maps/'+encodeURIComponent(identifier)+'/objects');if(version!==selectionVersion)return;const counts={};for(const view of report.observations||[])for(const detection of view.detections)counts[detection.label]=(counts[detection.label]||0)+1;element('objects').textContent='Trạng thái: '+report.state+'\n'+(Object.entries(counts).map(([label,count])=>label+': '+count+' lượt trên ảnh').join(' · ')||'Chưa có nhãn đủ tin cậy.')+'\n'+report.note}catch(error){if(version===selectionVersion)element('objects').textContent='Bản cũ chưa có báo cáo đồ vật.'}}
element('rename').onclick=async()=>{const name=prompt('Tên map (1–64 ký tự):',element('name').textContent);if(name===null)return;try{await api('/maps/'+selected+'/rename',{method:'POST',body:JSON.stringify({name})});await refresh();await show(selected)}catch(error){fail(error)}};
element('reload').onclick=()=>refresh().catch(fail);
element('upload').onclick=()=>{const file=element('file').files[0];if(!file){fail(Error('Chọn file ZIP trước.'));return}if(file.size>220*1024*1024){fail(Error('ZIP vượt 220 MB; chia lượt thu nhỏ hơn.'));return}const request=new XMLHttpRequest();request.open('POST','/capture');request.setRequestHeader('Authorization','Bearer '+config.token);request.setRequestHeader('Content-Type','application/zip');element('upload').disabled=true;request.upload.onprogress=event=>{if(event.lengthComputable)element('status').textContent='Đang gửi '+Math.round(event.loaded/event.total*100)+'% byte ZIP'};request.onload=()=>{element('upload').disabled=false;try{const data=JSON.parse(request.responseText);if(request.status>=400)throw Error(data.error);element('status').textContent='Đã nhận ZIP; PC đang phân tích.'}catch(error){fail(error)}};request.onerror=()=>{element('upload').disabled=false;fail(Error('Mất kết nối. ZIP gốc vẫn còn; thử lại.'))};request.send(file)};
async function poll(){try{const state=await api('/status');element('status').textContent=state.stage+(state.total?' · '+state.registered+'/'+state.total+' ảnh':'');if(state.state!==lastState){lastState=state.state;await refresh()}}catch(error){fail(error)}finally{setTimeout(poll,3000)}}poll();
</script></html>'''
    return template.replace("__CONFIG__", json.dumps({"token": token, "url": url})).encode("utf-8")
